import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdtemp, rm } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { createServer } from 'vite';
import { CommerceSceneSchema } from '@still-shift/scene-contract';
import { compileCommerceComposition } from '@still-shift/animation-engine';
import { compileCommerceScene } from '@still-shift/renderer-core';
import { launchRenderBrowser, probeRenderEnvironment, assertPinnedRenderEnvironment } from '@still-shift/execution-runtime';
import { commerceEffectVariants } from '../../../tests/helpers/composition-effects.ts';
import { commerceExposureVariants } from '../../../tests/helpers/composition-commerce-exposure.ts';

const root = resolve(import.meta.dirname,'../../..');
const baselineRef = '0e4838852855f6dc8cf91bba763a402dfd716f88';
const prefix = 'packages/renderer-core/src/composition/render/';
const paths = ['renderer.ts', 'webgl2.ts', 'webgl-bounds.ts'].map(p => prefix + p);
const source = Object.fromEntries(paths.map(p => [p, execFileSync('git', ['show', `${baselineRef}:${p}`], {cwd:root,encoding:'utf8'})]));
const candidateSources = await Promise.all([...paths, prefix+'webgl-exposure.ts'].map(async path => ({path, sha256:createHash('sha256').update(await readFile(join(root,path))).digest('hex')})));
const output=join(root,`benchmarks/results/composition-ce6p/preserved-echo-byte-proof-attempt-${Date.now()}.json`);
const diagnosticSource=await readFile(import.meta.filename,'utf8');
const provenance={baselineRef,candidateRef:execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim(),baselineSources:paths.map(path=>({path,sha256:createHash('sha256').update(source[path]).digest('hex')})),candidateSources,diagnosticSourceSha256:createHash('sha256').update(diagnosticSource).digest('hex'),diagnosticSource};
const suffix = '?ce6p-preserved';
const cache = await mkdtemp(join(tmpdir(), 'ce6p-preserved-'));
const server = await createServer({root,configFile:false,cacheDir:cache,logLevel:'error',plugins:[{name:'ce6p-preserved-consistent-source',enforce:'pre',load(id){
  if (!id.endsWith(suffix)) return;
  const p=id.slice(root.length+1,-suffix.length);
  if (!source[p]) return;
  return source[p].replace('"./webgl2.ts"','"./webgl2.ts'+suffix+'"').replace('"./webgl-bounds.ts"','"./webgl-bounds.ts'+suffix+'"');
}}],server:{host:'127.0.0.1',port:0}});
let browser;
const results=[];
try {
  await server.listen();
  browser=await launchRenderBrowser({profile:'pinned'});
  const page=await browser.newPage();
  await page.addInitScript('window.__name = (fn) => fn;');
  await page.goto(server.resolvedUrls!.local[0]!);
  const environment=await probeRenderEnvironment(page,'pinned');
  assertPinnedRenderEnvironment(environment);
  const inventory=JSON.parse(await readFile(join(root,'tests/visual/composition-baselines/fixtures.json'),'utf8'));
  for (const fixtureId of ['commerce/atom-echo','commerce/atom-motion-blur']) {
  const fixture=inventory.fixtures.find((f:any)=>f.id===fixtureId);
  const path=resolve(root,fixture.path);
  const input=CommerceSceneSchema.parse(JSON.parse(await readFile(path,'utf8')));
  const items=fixtureId==='commerce/atom-echo' ? [{id:fixture.id,scene:input},...commerceEffectVariants(fixture.id,input)] : commerceExposureVariants(fixture.id,input).filter(item=>item.id.endsWith('/overlap-echo-matte'));
  for (const item of items) {
    const composition=await compileCommerceComposition(item.scene,dirname(path));
    const scene=compileCommerceScene(item.scene);
    const urls=Object.fromEntries(composition.assets.map(a=>[a.id,`/@fs${resolve(dirname(path),a.path)}`]));
    const result=await page.evaluate(async ({composition,scene,urls,tier})=>{
      const m=await import('/packages/renderer-core/src/index.ts');
      const original=await import('/packages/renderer-core/src/composition/render/renderer.ts?ce6p-preserved');
      const resources=await m.loadCompositionResources(composition,(id:string)=>urls[id]);
      const previous=original.createCompositionPreview(document.createElement('canvas'),composition,resources,{backend:'webgl2'});
      const candidate=m.createCompositionPreview(document.createElement('canvas'),composition,resources,{backend:'webgl2'});
      const legacyCanvas=document.createElement('canvas');legacyCanvas.width=composition.width;legacyCanvas.height=composition.height;
      const legacy=m.createIllustratedPreview(legacyCanvas,scene,await m.loadIllustratedImages(scene,(id:string)=>urls[id]));
      const ctx=legacyCanvas.getContext('2d',{willReadFrequently:true})!;
      const n=composition.frameCount;
      const hashes:string[]=[];let maxCandidateDelta=0,differingChannels=0,readChecks=0;
      const metric=()=>({maxDelta:0,minPsnr:Infinity,failingFrames:[] as number[]});
      const previousLegacy=metric(),candidateLegacy=metric();
      const samples=new Set<number>();
      const hash=async(a:Uint8ClampedArray)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',a))).map(v=>v.toString(16).padStart(2,'0')).join('');
      async function check(frame:number,forward:boolean){
        const a=previous.renderFrame(frame),b=candidate.renderFrame(frame);samples.add(a.samples);samples.add(b.samples);
        const old=previous.readPixels(),next=candidate.readPixels();
        for(let i=0;i<old.length;i++){const d=Math.abs(old[i]-next[i]);maxCandidateDelta=Math.max(maxCandidateDelta,d);if(d)differingChannels++;}
        readChecks++;
        const h=await hash(next);if(forward)hashes[frame]=h;else if(h!==hashes[frame])throw new Error(`Candidate seek/repeat changed at ${frame}`);
        if(await hash(old)!==h)throw new Error(`Preserved renderer differs at ${frame}`);
        if(forward){legacy.renderFrame(frame);const expected=ctx.getImageData(0,0,composition.width,composition.height).data;
          for(const [actual,record] of [[old,previousLegacy],[next,candidateLegacy]] as const){const c=m.compareFrames(expected,actual,composition.width,composition.height);record.maxDelta=Math.max(record.maxDelta,c.maxChannelDelta);record.minPsnr=Math.min(record.minPsnr,c.psnr);if(!m.meetsTier(c,tier))record.failingFrames.push(frame);}
        }
      }
      try {
        for(let frame=0;frame<n;frame++)await check(frame,true);
        for(let frame=n-1;frame>=0;frame--)await check(frame,false);
        for(let i=0;i<17;i++)await check((i*73+31)%n,false);
        for(let i=0;i<3;i++)await check(Math.floor(n/2),false);
        const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(hashes.join('\n')));
        return {baselineVersion:previous.rendererVersion,candidateVersion:candidate.rendererVersion,frames:n,readChecks,order:['all forward','all reverse','17 deterministic random','3 repeated middle'],samples:[...samples],maxCandidateDelta,differingChannels,previousLegacy,candidateLegacy,forwardHashesSha256:Array.from(new Uint8Array(digest)).map(v=>v.toString(16).padStart(2,'0')).join('')};
      } finally {previous.dispose();candidate.dispose();}
    },{composition:JSON.parse(JSON.stringify(composition)),scene:JSON.parse(JSON.stringify(scene)),urls,tier:fixture.tier});
    results.push({id:item.id,...result});
    console.log(JSON.stringify({id:item.id,readChecks:result.readChecks,maxCandidateDelta:result.maxCandidateDelta,previousLegacyMax:result.previousLegacy.maxDelta,candidateLegacyMax:result.candidateLegacy.maxDelta}));
  }
  }
  const record=JSON.stringify({status:'passed',...provenance,environment,results},null,2)+'\n';
  await writeFile(output,record);
  await writeFile(join(root,'benchmarks/results/composition-ce6p/preserved-echo-byte-proof.json'),record);
} catch(error) {await writeFile(output,JSON.stringify({status:'failed',...provenance,results,error:String(error)},null,2)+'\n');throw error;}
finally {await browser?.close();await server.close();await rm(cache,{recursive:true,force:true});}
